'use strict';

// Full PP target registry: 9 video sites + 2 webtoon/comic sites.
// Used by -pptest / -ppsites. Scrapers live in ./pplib/scrapers.cjs.

const sites = [
  { key: 'xvideos', label: 'xVideos', domain: 'https://www.xvideos.com/', searchCmd: 'ppxvideos', kind: 'video' },
  { key: 'xnxx', label: 'XNXX', domain: 'https://www.xnxx.com/', searchCmd: 'ppxnxx', kind: 'video' },
  { key: 'pornhub', label: 'Pornhub', domain: 'https://www.pornhub.com/', searchCmd: 'pppornhub', kind: 'video' },
  { key: 'redgifs', label: 'Redgifs', domain: 'https://www.redgifs.com/', searchCmd: 'ppredgifs', kind: 'video' },
  { key: 'eporner', label: 'Eporner', domain: 'https://www.eporner.com/', searchCmd: 'ppeporner', kind: 'video' },
  { key: 'erome', label: 'Erome', domain: 'https://erome.com/', searchCmd: 'pperome', kind: 'video' },
  { key: 'tnaflix', label: 'TnaFlix', domain: 'https://www.tnaflix.com/', searchCmd: 'pptnaflix', kind: 'video' },
  { key: 'youporn', label: 'YouPorn', domain: 'https://www.youporn.com/', searchCmd: 'ppyouporn', kind: 'video' },
  { key: 'redtube', label: 'RedTube', domain: 'https://www.redtube.com/', searchCmd: 'ppredtube', kind: 'video' },
  { key: 'webtoons', label: 'WEBTOON', domain: 'https://www.webtoons.com/', searchCmd: 'ppwebtoon', kind: 'comic' },
  { key: 'tapas', label: 'Tapas', domain: 'https://tapas.io/', searchCmd: 'pptapas', kind: 'comic' },
];

const byKey = new Map(sites.map(site => [site.key, site]));

function getSite(value) {
  const key = String(value || '').trim().toLowerCase();
  return byKey.get(key) || null;
}

function siteListText(prefix = '-') {
  const videos = sites.filter((s) => s.kind === 'video');
  const comics = sites.filter((s) => s.kind === 'comic');
  const line = (s, i) => `${i + 1}. ${s.label} → ${prefix}${s.searchCmd} <search>`;
  return [
    '*VIDEO*',
    ...videos.map(line),
    '',
    '*WEBTOON / COMICS*',
    ...comics.map(line),
  ].join('\n');
}

async function checkHome(site, timeoutMs = 10000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  const started = Date.now();
  try {
    const response = await fetch(site.domain, {
      method: 'HEAD',
      redirect: 'follow',
      signal: controller.signal,
      headers: { 'user-agent': 'ABIX-PP-Owner-Diagnostic/1.0' },
    });
    return {
      ok: response.ok || response.status < 500,
      status: response.status,
      statusText: response.statusText,
      latency: Date.now() - started,
      finalUrl: response.url || site.domain,
    };
  } catch (error) {
    return {
      ok: false,
      status: 0,
      statusText: error?.name === 'AbortError' ? 'TIMEOUT' : (error?.message || 'FETCH_ERROR'),
      latency: Date.now() - started,
      finalUrl: site.domain,
    };
  } finally {
    clearTimeout(timer);
  }
}

module.exports = { sites, getSite, siteListText, checkHome };
